from common import *
R=[{'sourceId':'mit-algorithms','locator':'Lecture Notes: Sorting, Hashing, Graph Search, Shortest Paths, Dynamic Programming'},{'sourceId':'mit-discrete','locator':'Induction, State Machines, Asymptotic Notation'},{'sourceId':'solomon','locator':'Các mục numerical algorithms, linear solvers và optimization: tham khảo về thuật toán số, không thay giáo trình độ phức tạp'}]
s=[]
s.append(S('correctness-cost','Đặc tả, tính đúng và ký hiệu tiệm cận',r'Phân tích thuật toán gồm tiền điều kiện, hậu điều kiện, tính dừng và chi phí theo mô hình tính toán. O là chặn trên tiệm cận, Omega là chặn dưới và Theta là hai phía. § Phải phân biệt trường hợp xấu nhất, trung bình theo phân bố và kỳ vọng theo ngẫu nhiên nội tại. Kích thước đầu vào là số bit khi dữ liệu là số nguyên lớn; một vòng chạy đến N không đa thức theo log N.',r'Nêu đầu vào và hậu điều kiện. § Chọn phép toán cơ bản và kích thước biểu diễn. § Chứng minh bất biến, dừng rồi đếm chi phí.','Một số ít phép toán số học trên số nguyên khổng lồ không luôn có chi phí hằng.',[
E(r'Chứng minh $3n^2+2n+1=\Theta(n^2)$ với $n\ge1$.',r'Chặn dưới bởi $3n^2$. § Vì $n\le n^2$ và $1\le n^2$, chặn trên bởi $6n^2$. § Hai hằng số 3 và 6 cùng ngưỡng n=1 cho Theta.',r'Bậc tăng trưởng là $\Theta(n^2)$.','Ký hiệu Theta bỏ hệ số cố định nhưng không bỏ bậc n.'),
E(r'Hai vòng lặp: i từ 1 đến n, j từ 1 đến i. Có bao nhiêu lần chạy thân?',r'Với i cố định, thân chạy i lần. § Tổng số lần là $\sum_{i=1}^n i=n(n+1)/2$. § Hạng bậc cao nhất là n bình phương.',r'$n(n+1)/2=\Theta(n^2)$.','Cận vòng trong phụ thuộc vòng ngoài nên không nhân tùy tiện hai cận tối đa để có số chính xác.'),
E(r'Biến i bắt đầu từ 1, mỗi bước nhân 2 cho đến khi i ít nhất n. Số bước?',r'Sau k bước, i bằng $2^k$. § Dừng khi $2^k\ge n$. § Số nguyên k nhỏ nhất thỏa là $\lceil\log_2 n\rceil$.',r'$\Theta(\log n)$ bước.','Vòng lặp nhân đôi tạo tăng trưởng mũ của biến nhưng chi phí logarit.'),
E(r'Thuật toán duyệt từ 1 đến N có là đa thức theo độ dài nhị phân của N không?',r'N có độ dài $b=\lfloor\log_2N\rfloor+1$. § N có thể xấp xỉ $2^b$. § Chi phí Theta(N) vì vậy có thể tăng theo hàm mũ của b.',r'Không; đây có thể là thời gian giả đa thức theo giá trị số.','Mô hình bit quan trọng trong thuật toán số học và mật mã.'),
E(r'Tìm phần tử lớn nhất của mảng không rỗng bằng quét: nêu bất biến và chi phí.',r'Sau khi xử lý i phần tử, biến max là lớn nhất của tiền tố đó. § So sánh phần tử i+1 và cập nhật bảo toàn bất biến; chỉ số tăng nên dừng. § Cần n-1 phép so sánh và O(1) bộ nhớ phụ.',r'Tính đúng với thời gian $\Theta(n)$.','Đầu vào không rỗng là tiền điều kiện để khởi tạo max bằng phần tử đầu.')],R))
s.append(S('divide-conquer','Chia để trị và giải truy hồi thời gian',r'Chia để trị tách bài toán thành các bài con, giải chúng rồi kết hợp. Truy hồi cần chứa chi phí chia và ghép, cùng điều kiện cơ sở. § Với $T(n)=aT(n/b)+f(n)$, định lý Master so sánh f với $n^{\log_ba}$ dưới điều kiện từng trường hợp. Không áp dụng máy móc nếu kích thước bài con không đều hoặc điều kiện regularity không thỏa; có thể dùng cây truy hồi hoặc thế quy nạp.',r'Viết số lượng và kích thước bài con. § Tính chi phí ghép theo từng mức. § Cộng các mức và kiểm tra điều kiện cơ sở.','Kích thước bài con và số bài con là hai tham số khác nhau.',[
E(r'Giải $T(n)=2T(n/2)+n$, n là lũy thừa 2.',r'Mức đầu có chi phí n, mức kế có hai bài n/2 nên tổng cũng n. § Có log2 n mức trước cơ sở. § Cộng chi phí mức và O(n) lá.',r'$T(n)=\Theta(n\log n)$.','Cân bằng chi phí mỗi mức là dấu hiệu điển hình của merge sort.'),
E(r'Giải $T(n)=T(n/2)+1$.',r'Mỗi mức chỉ có một bài con nửa kích thước. § Sau k mức còn n/2^k; đạt 1 khi k=log2 n. § Mỗi mức tốn hằng số.',r'$\Theta(\log n)$.','Đây là truy hồi chi phí tìm kiếm nhị phân.'),
E(r'Giải $T(n)=4T(n/2)+n$.',r'$n^{\log_2 4}=n^2$. § Chi phí ghép n nhỏ hơn n bình phương theo một bậc đa thức. § Trường hợp thứ nhất của Master cho chi phí chi phối ở các lá.',r'$\Theta(n^2)$.','Nhiều bài con hơn có thể lấn át chi phí ghép tuyến tính.'),
E(r'Giải $T(n)=T(n-1)+n$, T(1) hằng.',r'Mở truy hồi thành $T(1)+2+3+\cdots+n$. § Tổng cấp số cộng bằng $n(n+1)/2-1$. § Vì vậy chi phí tăng bậc hai.',r'$\Theta(n^2)$.','Master không phù hợp vì kích thước giảm 1 chứ không giảm theo tỷ lệ.'),
E(r'Tìm kiếm nhị phân phần tử 13 trong mảng [1,4,7,9,13,18,21].',r'Giữa mảng là 9, nên bỏ nửa trái. § Giữa phần còn lại là 18, nên bỏ phía lớn hơn 18. § Còn vị trí có 13; các khoảng tìm kiếm đều giữ mọi vị trí có thể chứa khóa.',r'Tìm thấy 13 với 3 phép so sánh khóa trong quy trình này.','Bất biến miền ứng viên là phần chứng minh tính đúng, không chỉ việc chia đôi.')],R))
s.append(S('sorting-structures','Sắp xếp, heap, bảng băm và chặn dưới',r'Các thuật toán sắp xếp so sánh có chặn dưới trường hợp xấu nhất Omega(n log n), suy từ số lá của cây quyết định ít nhất n! với khóa phân biệt. Counting sort không thuộc mô hình chỉ so sánh. § Heap hỗ trợ cực trị qua cấu trúc cây gần hoàn chỉnh; bảng băm cần mô hình phân phối khóa hoặc hàm băm để có kỳ vọng tốt. Kỳ vọng O(1) không phải bảo đảm trường hợp xấu nhất.',r'Chọn cấu trúc theo thao tác cần hỗ trợ. § Nêu điều kiện về miền khóa và mô hình ngẫu nhiên. § Tách chi phí xây dựng, tìm, cập nhật.','Sắp xếp tại chỗ và sắp xếp ổn định là hai tính chất khác nhau.',[
E(r'Insertion sort trên mảng đã tăng: cần bao nhiêu phép so sánh chính?',r'Mỗi phần tử từ vị trí thứ hai so với tiền nhiệm rồi dừng. § Có n-1 lần chèn. § Tổng phép so sánh chính là n-1, nên thời gian tuyến tính.',r'$\Theta(n)$ ở trường hợp thuận lợi này.','Trường hợp xấu nhất của cùng thuật toán vẫn là bậc hai.'),
E(r'Tại sao sorting bằng so sánh cần Omega(n log n) ở trường hợp xấu nhất?',r'Có n! thứ tự của n khóa phân biệt. § Cây so sánh nhị phân độ cao h có nhiều nhất $2^h$ lá. § Cần $2^h\ge n!$, nên $h\ge\log_2(n!)=\Omega(n\log n)$.',r'Chặn dưới áp dụng cho mô hình so sánh.','Một thuật toán dựa trên miền khóa hữu hạn có thể vượt chặn mà không mâu thuẫn.'),
E(r'Xóa cực đại khỏi max-heap [9,7,8,3,2,6,5].',r'Đưa phần tử cuối 5 lên gốc và bỏ nút cuối. § Đổi 5 với con lớn hơn 8, rồi đổi 5 với con 6. § Thu heap [8,7,6,3,2,5], mọi cha vẫn không nhỏ hơn con.',r'Heap mới [8,7,6,3,2,5].','Sửa heap chỉ đi theo một nhánh dài O(log n).'),
E(r'Bảng băm chaining có n=100 khóa, m=20 ô. Hệ số tải là bao nhiêu?',r'Hệ số tải alpha bằng n/m. § Thay số được 5. § Dưới băm đều thích hợp, độ dài danh sách kỳ vọng theo một ô là 5, không đảm bảo mọi ô đúng 5.',r'$\alpha=5$.','Giả thiết phân phối băm cần đi kèm kết luận thời gian kỳ vọng.'),
E(r'Counting sort với n phần tử có khóa trong 0 đến k-1 tốn bao nhiêu?',r'Khởi tạo và duyệt bảng đếm tốn O(k). § Đếm và xuất hoặc phân phối n phần tử tốn O(n). § Tổng thời gian O(n+k), bộ nhớ tùy phiên bản nhưng có ít nhất bảng O(k).',r'$O(n+k)$.','Lợi ích chỉ có khi phạm vi khóa k không quá lớn so với n.')],R))
s.append(S('dynamic-programming','Quy hoạch động và khôi phục lời giải',r'Quy hoạch động xác định trạng thái đủ thông tin, quan hệ truy hồi và thứ tự tính không có vòng phụ thuộc. Nó tái sử dụng các bài con trùng nhau thay vì gọi lặp. § Cần chứng minh cấu trúc tối ưu: nghiệm tối ưu của trạng thái có thể ghép từ các lựa chọn và bài con tương ứng. Ngoài giá trị tối ưu, lưu quyết định hoặc truy vết để khôi phục lời giải. Số trạng thái nhân chi phí chuyển là cách tính thời gian.',r'Định nghĩa trạng thái bằng một câu rõ nghĩa. § Viết cơ sở và mọi lựa chọn chuyển. § Tính đúng thứ tự rồi truy vết.','Viết công thức mà không định nghĩa trạng thái dễ tạo lỗi chỉ số hoặc bỏ trường hợp.',[
E(r'Tính Fibonacci thứ 5 bằng DP với F0=0,F1=1.',r'Dùng $F_i=F_{i-1}+F_{i-2}$. § Lần lượt nhận 1,2,3,5 ở các chỉ số 2,3,4,5. § Chỉ cần giữ hai giá trị cuối nếu không yêu cầu lưu toàn bảng.',r'$F_5=5$, thời gian O(n), bộ nhớ phụ O(1).','DP tránh cây đệ quy tính lặp cùng các số Fibonacci.'),
E(r'Đổi 6 đơn vị bằng đồng {1,3,4} sao cho ít đồng nhất.',r'Đặt $D(0)=0$, $D(v)=1+\min_{c\le v}D(v-c)$. § Tính D1=1,D2=2,D3=1,D4=1,D5=2. § D6 bằng $1+D3=2$, chọn hai đồng 3.',r'2 đồng: 3+3.','Tham lam chọn 4 trước cho 3 đồng, không tối ưu trong hệ tiền này.'),
E(r'Ba lô 0/1 sức chứa 5, vật (trọng lượng,giá trị) là (2,3),(3,4),(4,5).',r'Trạng thái D(i,w) chỉ dùng i vật đầu. § Với vật i, lấy lớn nhất giữa bỏ vật và lấy nó cộng D(i-1,w-wi). § Ở sức chứa 5, lấy hai vật đầu cho giá trị 7, lớn hơn lấy vật ba được 5.',r'Giá trị tối ưu 7.','Dùng hàng i-1 ngăn cùng một vật bị lấy nhiều lần trong bài 0/1.'),
E(r'Tìm độ dài dãy con chung dài nhất của ABC và AC.',r'DP theo hai tiền tố; nếu ký tự cuối trùng thì cộng 1 từ ô chéo. § Nếu không trùng, lấy max của hai ô bỏ một ký tự. § Dãy AC xuất hiện theo thứ tự trong cả hai, và chuỗi thứ hai chỉ dài 2.',r'LCS có độ dài 2.','Dãy con không yêu cầu các ký tự phải liên tiếp.'),
E(r'Đếm đường đi trong lưới 2 nhân 2 ô khi chỉ đi phải hoặc xuống từ góc trái trên đến phải dưới.',r'Cần 2 bước phải và 2 bước xuống. § DP mỗi nút nhận tổng số đường từ trên và trái, biên có 1 đường. § Ô đích nhận 6; đối chiếu tổ hợp chọn 2 trong 4 bước.',r'6 đường đi.','Hai cách tính độc lập kiểm tra được cả mô hình và chỉ số lưới.')],R))
s.append(S('greedy-amortized','Tham lam, trao đổi và phân tích khấu hao',r'Thuật toán tham lam chọn quyết định cục bộ rồi không quay lại. Muốn kết luận tối ưu phải có chứng minh như trao đổi, tính chất lát cắt hoặc cấu trúc matroid; ví dụ thành công riêng lẻ chưa đủ. § Phân tích khấu hao chặn tổng chi phí cả chuỗi thao tác, không lấy kỳ vọng theo xác suất. Phương pháp tổng, kế toán hoặc thế năng giải thích vì sao một số thao tác đắt vẫn cho chi phí khấu hao thấp.',r'Nêu quy tắc chọn. § Chứng minh đổi một nghiệm tối ưu để chứa lựa chọn đó. § Với cấu trúc động, chặn tổng chi phí chuỗi thao tác.','Đừng nhầm chi phí khấu hao O(1) với mọi thao tác đều có thời gian thực O(1).',[
E(r'Chọn nhiều khoảng không giao nhau nhất: [1,3],[2,5],[3,4],[4,6], cho phép chạm đầu mút.',r'Sắp theo thời điểm kết thúc, chọn [1,3]. § Khoảng tương thích kết thúc sớm nhất tiếp theo là [3,4], rồi [4,6]. § Lập luận trao đổi thay khoảng đầu của nghiệm tối ưu bằng khoảng kết thúc sớm nhất không làm giảm số lựa chọn còn lại.',r'Chọn được 3 khoảng.','Quy ước cho phép chạm đầu mút phải được nói rõ.'),
E(r'Tại sao chọn đồng tiền lớn nhất không luôn tối ưu với {1,3,4}?',r'Với số tiền 6, tham lam lấy 4 rồi 1 rồi 1. § Cách này dùng 3 đồng. § Nhưng 3+3 dùng 2 đồng, nên là một phản ví dụ đủ bác bỏ tính tối ưu tổng quát.',r'Tham lam thất bại ở 6.','Cần chứng minh cho hệ tiền cụ thể, không suy từ cảm giác trực giác.'),
E(r'Mảng động tăng gấp đôi từ dung lượng 1. Chi phí sao chép để thêm 8 phần tử?',r'Các lần tăng dung lượng sao chép 1,2,4 phần tử. § Tổng sao chép 7; ghi 8 phần tử mới thêm 8 thao tác. § Tổng mô hình chi phí là 15, nhỏ hơn 2n với n=8.',r'15 thao tác ghi/sao chép trong mô hình này.','Một lần tăng có thể O(n), nhưng chi phí bình quân trên chuỗi là hằng số.'),
E(r'Stack hỗ trợ push,pop và multipop. Vì sao tổng pop của n lần push không vượt n?',r'Mỗi phần tử chỉ được đưa vào một lần qua một push. § Sau khi pop, nó không thể pop lần nữa trừ khi được push mới. § Gán mỗi pop cho push tạo ra nó, thu số pop không vượt số push.',r'Tổng chi phí các lần lấy ra là O(n).','Hạch toán theo vòng đời phần tử cho một chặn khấu hao trực tiếp.'),
E(r'Tìm cây khung nhỏ nhất của tam giác có AB=1,BC=2,AC=3.',r'Kruskal chọn cạnh AB nhẹ nhất. § Chọn tiếp BC không tạo chu trình, đủ n-1 cạnh. § Tổng 3; hai cây còn lại có tổng 4 hoặc 5.',r'MST gồm AB,BC, tổng trọng số 3.','Tính chất lát cắt là cơ sở chứng minh Kruskal, không chỉ thứ tự tăng trọng số.')],R))
s.append(S('shortest-paths','Tìm kiếm đồ thị, DAG và đường đi ngắn nhất',r'BFS tìm đường ngắn theo số cạnh trên đồ thị không trọng số; DFS hỗ trợ khám phá, thành phần và thứ tự topo. DAG có thể giải đường ngắn bằng thư giãn theo topo, kể cả trọng số âm. § Dijkstra yêu cầu trọng số không âm để chốt một đỉnh an toàn. Bellman–Ford cho phép cạnh âm và phát hiện chu trình âm có thể tới từ nguồn; khi chu trình âm ảnh hưởng đích, khoảng cách ngắn nhất hữu hạn không tồn tại.',r'Xác định hướng và trọng số. § Chọn thuật toán phù hợp giả thiết. § Ghi phép thư giãn và truy vết cha.','Không dùng BFS thay Dijkstra khi số cạnh ít nhất không đồng nghĩa tổng trọng số nhỏ nhất.',[
E(r'Đồ thị có s→a trọng số 2, s→b là 5, a→b là 1. Tìm khoảng cách từ s.',r'Ban đầu d(s)=0, hai khoảng cách ứng viên là 2 và 5. § Chốt a trước, thư giãn a→b cho d(b)=3. § Chốt b; đường qua a tốt hơn cạnh trực tiếp.',r'$d(a)=2$, $d(b)=3$.','Thư giãn là phép thay chặn trên bằng một đường tốt hơn đã tìm thấy.'),
E(r'Vì sao Dijkstra chốt đỉnh có thể sai với s→a=2,s→b=5,b→a=-4?',r'Thuật toán chốt a ở khoảng cách 2 trước b. § Sau khi xét b, đường s→b→a có trọng số 1. § Một đỉnh đã chốt cần sửa xuống, phá bất biến của Dijkstra chuẩn.',r'Khoảng cách đúng tới a là 1, không phải 2.','Không âm là giả thiết của chứng minh, không là chi tiết tùy chọn.'),
E(r'DAG có s→a=3,s→b=2,b→a=-2,a→t=4. Tính đường ngắn s đến t.',r'Một thứ tự topo là s,b,a,t. § Sau s, d(b)=2 và d(a)=3; cạnh b→a giảm d(a) xuống 0. § Cạnh a→t cho d(t)=4.',r'Đường s→b→a→t có tổng 4.','DAG không có chu trình nên cạnh âm không gây lặp giảm vô hạn.'),
E(r'Đồ thị có chu trình a→b trọng số 1, b→a=-2, tới được từ s. Có khoảng cách ngắn nhất tới a?',r'Tổng trọng số chu trình bằng $-1$. § Mỗi lần đi quanh chu trình làm tổng đường giảm thêm 1. § Có thể lặp tùy ý nên không có giá trị nhỏ nhất hữu hạn.',r'Không có khoảng cách ngắn nhất hữu hạn tới a.','Kết luận áp dụng cho các đỉnh bị chu trình âm ảnh hưởng và tới được từ nguồn.'),
E(r'Độ phức tạp BFS trên danh sách kề?',r'Mỗi đỉnh được đánh dấu và vào hàng đợi tối đa một lần. § Mỗi mục cạnh trong danh sách được duyệt hữu hạn lần, một hoặc hai tùy đồ thị. § Tổng là O(V+E), bộ nhớ O(V) ngoài biểu diễn đồ thị.',r'$O(|V|+|E|)$.','Độ phức tạp sẽ khác nếu biểu diễn bằng ma trận kề cần quét mọi cặp.')],R))
s.append(S('flow-matching','Luồng cực đại, lát cắt và ghép cặp',r'Luồng tuân dung lượng cạnh và bảo toàn ở các đỉnh trung gian. Mạng dư cho phép tăng trên cạnh thuận và hủy một phần luồng trước bằng cạnh ngược. Giá trị mọi luồng không vượt dung lượng mọi lát cắt s–t. § Khi không còn đường tăng, tập đỉnh tới được trong mạng dư tạo lát cắt cùng giá trị, chứng minh tối ưu. Ghép cặp hai phía được chuyển sang luồng bằng cạnh dung lượng 1.',r'Viết dung lượng và bảo toàn. § Tìm đường tăng trong mạng dư có cạnh ngược. § Dùng lát cắt làm chứng cứ tối ưu.','Không có cạnh ngược sẽ có thể mắc kẹt ở lựa chọn luồng chưa tối ưu.',[
E(r'Mạng s→a=3,s→b=2,a→t=2,b→t=3,a→b=1. Tìm max-flow.',r'Gửi 2 theo s-a-t và 2 theo s-b-t. § Gửi thêm 1 theo s-a-b-t, tổng 5, không vượt dung lượng nào. § Lát cắt chỉ gồm s có dung lượng 3+2=5 nên không thể tốt hơn.',r'Luồng cực đại bằng 5.','Luồng khả thi và lát cắt cùng giá trị là chứng chỉ tối ưu hoàn chỉnh.'),
E(r'Mạng duy nhất s→a dung lượng 4, a→t dung lượng 7. Max-flow?',r'Bảo toàn yêu cầu lượng đi qua hai cạnh bằng nhau. § Cạnh đầu chỉ cho tối đa 4. § Gửi 4 là khả thi, và lát cắt đầu có dung lượng 4.',r'4.','Nút thắt cổ chai của một đường là dung lượng nhỏ nhất trên đường.'),
E(r'Bipartite: trái {u,v}, phải {a,b}, cạnh u-a,u-b,v-a. Ghép cặp cực đại?',r'Chọn u-b và v-a, không dùng đỉnh nào hai lần. § Được 2 cạnh. § Phía trái chỉ có 2 đỉnh nên không có ghép cặp lớn hơn.',r'Kích thước cực đại bằng 2.','Lựa chọn tham lam u-a ban đầu có thể cần đường tăng để sửa.'),
E(r'Đã ghép u-a trong đồ thị trên. Đường tăng nào cải thiện?',r'Đỉnh v chưa ghép và có cạnh tới a. § Đi luân phiên v-a-u-b: cạnh v-a chưa ghép, a-u đang ghép, u-b chưa ghép. § Đảo trạng thái các cạnh trên đường để được v-a và u-b.',r'Kích thước tăng từ 1 lên 2.','Đường tăng giữ nguyên điều kiện ghép cặp sau khi đảo.'),
E(r'Vì sao giá trị luồng không vượt dung lượng một lát cắt?',r'Cộng phương trình bảo toàn trên các đỉnh phía chứa s. § Luồng nội bộ triệt tiêu, chỉ còn luồng ra trừ luồng vào qua lát cắt. § Luồng vào không âm và luồng ra bị chặn bởi tổng dung lượng cạnh đi ra.',r'$|f|\le c(S,\bar S)$.','Đây là chặn trên độc lập với cách tìm luồng cụ thể.')],R))
s.append(S('complexity','P, NP, phép giảm và thuật toán xấp xỉ',r'P là các bài toán quyết định giải được trong thời gian đa thức; NP có chứng chỉ kích thước đa thức kiểm tra được trong thời gian đa thức. NP không có nghĩa là không đa thức. § Phép giảm đa thức $A\le_p B$ chuyển một bộ giải B thành bộ giải A, nên để chứng minh B khó phải giảm từ bài đã biết khó sang B. NP-complete cần cả thuộc NP và NP-hard. Xấp xỉ đòi một chặn tỷ lệ được chứng minh, không chỉ nghiệm nhìn khá tốt.',r'Phân biệt quyết định và tối ưu. § Nêu chứng chỉ và chiều phép giảm. § Chứng minh cả hai chiều tương đương hoặc chặn tỷ lệ.','Một ví dụ khó hoặc thuật toán chậm hiện có không chứng minh NP-hard.',[
E(r'Vì sao CLIQUE thuộc NP?',r'Chứng chỉ là danh sách k đỉnh. § Kiểm tra danh sách không lặp và mọi cặp có cạnh, cần O(k^2) phép kiểm tra với biểu diễn phù hợp. § Kích thước chứng chỉ và thời gian kiểm tra đa thức theo đầu vào.',r'CLIQUE thuộc NP.','Kiểm tra một chứng chỉ có thể dễ hơn tìm ra nó.'),
E(r'Cho công thức CNF có m mệnh đề. Mô tả ý chính giảm SAT dạng này sang clique chọn một literal mỗi mệnh đề.',r'Tạo đỉnh cho từng lần xuất hiện literal, chia theo mệnh đề. § Nối hai đỉnh thuộc mệnh đề khác nhau nếu literal không đối nhau. § Một clique kích thước m chọn một literal nhất quán từ mỗi mệnh đề; ngược lại một phép gán thỏa chọn ra clique như vậy.',r'Kiểm tra clique kích thước m mã hóa tính thỏa CNF qua cấu trúc này.','Đỉnh là lần xuất hiện literal; không nối hai đỉnh cùng mệnh đề.'),
E(r'Nếu một bài NP-complete có thuật toán đa thức, điều gì suy ra?',r'Mọi bài trong NP giảm đa thức về bài đó. § Hợp phép chuyển đổi và bộ giải đa thức vẫn là đa thức. § Suy ra NP nằm trong P, và P vốn nằm trong NP.',r'$P=NP$.','Đây là kết luận điều kiện, không khẳng định hiện đã biết P bằng NP.'),
E(r'Lấy hai đầu mỗi cạnh của một matching cực đại theo bao hàm để tạo vertex cover. Chứng minh tỷ lệ 2.',r'Nếu còn cạnh không được phủ thì cả hai đầu đều chưa ghép, có thể thêm cạnh, trái tính cực đại. § Mọi cover phải chọn ít nhất một đầu cho mỗi cạnh matching rời nhau, nên OPT ít nhất |M|. § Nghiệm chọn đúng $2|M|\le2OPT$ đỉnh.',r'Đây là thuật toán xấp xỉ 2 cho vertex cover không trọng số.','Matching cực đại theo bao hàm đủ dùng, không cần matching lớn nhất.'),
E(r'Ba lô DP O(nW) với W là sức chứa có phải luôn là thuật toán đa thức theo bit không?',r'W được viết bằng O(log W) bit. § Thời gian tuyến tính theo W có thể mũ theo số bit đó. § Vì vậy O(nW) là giả đa thức, dù hữu ích khi W vừa phải.',r'Không luôn đa thức theo độ dài mã hóa.','Phân biệt này quan trọng khi bàn độ khó và thiết kế xấp xỉ.')],R))
save('cse-496',['CSE 191, lập trình cơ bản, cấu trúc dữ liệu'],['Chứng minh thuật toán và phân tích theo mô hình đầu vào','Thiết kế chia để trị, DP, tham lam và thuật toán đồ thị','Hiểu giảm đa thức, NP và bảo đảm xấp xỉ'],s)
